131	// SetProvider updates the provider and optionally the model, clearing any stale
132	// model from the previous provider when switching without a replacement.
133	// An empty newProvider preserves the current provider; an empty newModel
134	// preserves the current model unless the provider is changing, in which case
135	// the old model is cleared to avoid passing (say) a Claude model to Codex.
136	func (s *SummaryGenerationSettings) SetProvider(newProvider, newModel string) {
137		if s == nil {
138			return
139		}
140		if newProvider != "" && s.Provider != "" && s.Provider != newProvider && newModel == "" {
141			s.Model = ""
142		}
143		if newProvider != "" {
144			s.Provider = newProvider
145		}
146		if newModel != "" {
147			s.Model = newModel
148		}
149	}
