186	// Load loads the Entire settings from .entire/settings.json,
187	// then applies any overrides from .entire/settings.local.json if it exists.
188	// Returns default settings if neither file exists.
189	// Works correctly from any subdirectory within the repository.
190	func Load(ctx context.Context) (*EntireSettings, error) {
191		// Get absolute paths for settings files
192		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
193		if err != nil {
194			settingsFileAbs = EntireSettingsFile // Fallback to relative
195		}
196		localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
197		if err != nil {
198			localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
199		}
200	
201		return loadMergedSettings(settingsFileAbs, localSettingsFileAbs)
202	}
203	
204	func loadMergedSettings(settingsFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
205		// Load base settings
206		settings, err := loadFromFile(settingsFileAbs)
207		if err != nil {
208			return nil, fmt.Errorf("reading settings file: %w", err)
209		}
210	
211		// Apply local overrides if they exist
212		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
213		if err != nil {
214			if !os.IsNotExist(err) {
215				return nil, fmt.Errorf("reading local settings file: %w", err)
216			}
217			// Local file doesn't exist, continue without overrides
218		} else {
219			if err := mergeJSON(settings, localData); err != nil {
220				return nil, fmt.Errorf("merging local settings: %w", err)
221			}
222		}
223	
224		// Re-validate after merge. Individual files are validated by loadFromFile,
225		// but mergeJSON patches fields independently and can produce combinations
226		// (e.g. model without provider when the local override sets only a model
227		// on top of a base with no provider) that neither file alone contained.
228		if err := settings.SummaryGeneration.Validate(); err != nil {
229			return nil, fmt.Errorf("merged settings invalid: %w", err)
230		}
231	
232		return settings, nil
233	}
234	
235	// LoadFromFile loads settings from a specific file path without merging local overrides.
236	// Returns default settings if the file doesn't exist.
237	// Use this when you need to display individual settings files separately.
238	func LoadFromFile(filePath string) (*EntireSettings, error) {
239		return loadFromFile(filePath)
240	}
