242	// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
243	// Use this when you have settings content from a non-file source (e.g., git show).
244	func LoadFromBytes(data []byte) (*EntireSettings, error) {
245		s := &EntireSettings{Enabled: true}
246		dec := json.NewDecoder(bytes.NewReader(data))
247		dec.DisallowUnknownFields()
248		if err := dec.Decode(s); err != nil {
249			return nil, fmt.Errorf("parsing settings: %w", err)
250		}
251		return s, nil
252	}
253	
254	// loadFromFile loads settings from a specific file path.
255	// Returns default settings if the file doesn't exist.
256	func loadFromFile(filePath string) (*EntireSettings, error) {
257		settings := &EntireSettings{
258			Enabled: true, // Default to enabled
259		}
260	
261		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
262		if err != nil {
263			if os.IsNotExist(err) {
264				return settings, nil
265			}
266			return nil, fmt.Errorf("%w", err)
267		}
268	
269		dec := json.NewDecoder(bytes.NewReader(data))
270		dec.DisallowUnknownFields()
271		if err := dec.Decode(settings); err != nil {
272			return nil, fmt.Errorf("parsing settings file: %w", err)
273		}
274	
275		// Validate commit_linking if set
276		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
277			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
278		}
279	
280		// SummaryGeneration is NOT validated here — individual files may
281		// legitimately contain only a model (provider comes from another file).
282		// Validation happens after merge in Load().
283	
284		return settings, nil
285	}
